42:     public string? PhoneNumber { get; set; }
43:     public string? AdmissionFrom { get; set; }
44:     public string? AdmissionTo { get; set; }
45:     public int Page { get; set; } = 1;
46:     public int PageSize { get; set; } = 20;
47:     public string SortKey { get; set; } = "studentNo";
48:     public string SortDirection { get; set; } = "asc";
49: }
50: public sealed record StudentRow(long StudentId, string StudentNo, string StudentName, string StudentNameKana,
51:     DateOnly BirthDate, int? SchoolYear, string? GradeName, string? ClassCode, string? ClassName,
52:     string? EnrollmentStatusName, string Address, string? PhoneNumber, DateOnly AdmissionDate,
53:     DateTimeOffset UpdatedAt, long RowVersion)
54: {
55:     public string BirthDateWareki => JapaneseDateService.ToWareki(BirthDate);
56: }
57: public sealed record SearchResult(Outcome Outcome, int Count, IReadOnlyList<StudentRow> Items,
58:     DateTimeOffset SearchedAt, bool LimitExceeded, IReadOnlyList<FieldError> Errors);
59: public sealed record StudentDetail(long StudentId, long RowVersion, StudentDraft Draft,
60:     DateOnly BirthDate, DateTimeOffset UpdatedAt, string UpdatedBy);
61: public sealed record CodeEntry(string CategoryId, string CodeValue, string CodeName, int DisplayOrder,
62:     bool IsActive, DateOnly ValidFrom, DateOnly? ValidTo, bool IsProtected);
63: public sealed record SchoolClass(long ClassId, int SchoolYear, string GradeCode, string ClassCode,
64:     string ClassName, DateOnly ValidFrom, DateOnly ValidTo, int? Capacity, int Occupied, bool IsActive);
65: public sealed record LookupSet(IReadOnlyList<CodeEntry> Codes, IReadOnlyList<SchoolClass> Classes);
