25:     private async Task<IActionResult> Load(long? id,string? context,CancellationToken ct) {var data=await coordinator.Edit(id,context,ct);var returnRevision=string.IsNullOrEmpty(context)?null:contexts.Get(context,identity.CurrentUser).Revision.ToString(System.Globalization.CultureInfo.InvariantCulture);return View("Edit",new StudentEditPageModel {StudentId=id,Input=data.Form,Detail=data.Detail,Lookups=data.Lookups,User=identity.CurrentUser,ReturnRevision=returnRevision,SnapshotId=snapshots.Create(identity.CurrentUser,id,data.Detail,data.Form,returnRevision)});}
