30:         if(ModelState.IsValid) {try {result=await coordinator.Save(id,input,ct);foreach(var e in result.Errors)ModelState.AddModelError(e.Field,e.Message);}catch(WebFault e){ModelState.AddModelError(e.Field??"",e.Message);Response.StatusCode=e.Status;} } else Response.StatusCode=422;
31:         if(result?.Outcome==Outcome.Saved)return ReturnAfterSave(input.ReturnContextId,snapshot.ReturnRevision,"保存しました。");
32:         if(result is not null){Response.StatusCode=WebPresentation.Status(result.Outcome);input.DuplicateToken=result.ConfirmationToken;ModelState.Remove("Input.DuplicateToken");}
33:         return View("Edit",new StudentEditPageModel {StudentId=id,Input=input,Detail=snapshot.Detail,SnapshotId=snapshotId,ReturnRevision=snapshot.ReturnRevision,Result=result,Lookups=await service.LookupAsync(ct),User=identity.CurrentUser,Message=result?.Outcome==Outcome.NoChange?"変更はありません。":""});
